 $('#wx-login').disabled=!auth.loggedIn&&!auth.webReady&&!auth.oaReady;$('#wx-login').textContent=auth.loggedIn?'退出微信登录':auth.webReady||auth.oaReady?'微信登录':'微信提醒待配置';$('#wx-status').textContent=auth.notificationReady?(auth.officialBound?'微信发送通道已配置；登录后可额外订阅公众号提醒。':'微信发送通道已配置，需绑定公众号身份后发送。'):'本机订阅与站内提醒已可使用。公众号、模板及发送凭证尚未配置，当前不会向微信发送提醒。';
