function observedItem(group){return group.current??group.lastObserved??group.item??null}
function remaining(end){const ms=Date.parse(end)-Date.now();if(!Number.isFinite(ms))return '官方尚未返回截止时间';if(ms<=0)return '已截止';const minutes=Math.ceil(ms/60000);return minutes>=60?`距截止约 ${Math.floor(minutes/60)} 小时 ${minutes%60} 分钟`:`距截止约 ${minutes} 分钟`}
