async function refreshLiveLottery(){if(liveRefreshing)return;liveRefreshing=true;render();$('#lottery-message').textContent='正在独立查询最新上架商品并核验抽签详情，通常需要十几至几十秒…';try{const name=$('#lottery-filter-skin').value,type=name?catalog.find(c=>c.name===name)?.id:'';if(name&&!type)throw Error('谪星目录尚未就绪，请稍后再试');const response=await fetch('/api/lottery/refresh'+(type?'?'+new URLSearchParams({type}):''),{method:'POST',signal:AbortSignal.timeout(60000)});const summary=await response.json();if(Array.isArray(summary.groups)){marketData={...marketData,lottery:summary};render()}if(!response.ok)throw Error(summary.error||'实时刷新未完成');$('#lottery-message').textContent=response.status===202?'其他访客已发起刷新，正在共享本轮结果；下方标注了该轮查询范围。':'抽签独立查询已完成。价格、星格和截止时间以实际核验记录为准。';if(response.status===202)setTimeout(refreshLottery,5000)}catch(error){$('#lottery-message').textContent=error.name==='TimeoutError'?'本次查询超时，旧记录已保留；稍后读取本轮结果或重新核验。':error.message}finally{liveRefreshing=false;render()}}
async function refreshStorage(){try{const response=await fetch('/api/storage',{cache:'no-store'});if(!response.ok)return;const data=await response.json(),policy=data.policy;$('#lottery-storage-status').textContent=`数据保留 · 每${policy.cleanupIntervalHours/24}天清理一次，届时删除超过${policy.retainHours/24}天的明细；抽签史低汇总与其样本保留。库存上限${policy.maxInventory.toLocaleString()}件、观察记录${policy.maxObservations.toLocaleString()}条、行情批次${policy.maxBatches}批，超限随采集轮次淘汰最旧记录。当前保留${data.counts.inventory.toLocaleString()}件 / ${data.counts.observations.toLocaleString()}条观察 / ${data.counts.batches}批${data.tableBytes?'，业务表约'+(data.tableBytes/1024/1024).toFixed(1)+' MB':''}；统计于${time(data.at)}，下次周期清理${time(data.nextCleanupAt)}。`}catch{}}
