async function refreshLottery(){if(lotteryLoading)return;lotteryLoading=true;try{const response=await fetch('/api/lottery',{cache:'no-store',signal:AbortSignal.timeout(20000)});if(!response.ok)return;const summary=await response.json();if(!Array.isArray(summary.groups))return;marketData={...marketData,lottery:summary};render()}catch{}finally{lotteryLoading=false}}
function safeURL(value){try{const u=new URL(value);return u.protocol==='https:'&&u.hostname==='yjwujian.cbg.163.com'}catch{return false}}
async function verify(item,button){button.disabled=true;const status=$('#lottery-action-status');status.textContent='正在向藏宝阁核验当前状态…';try{const response=await fetch('/api/lottery/verify?'+new URLSearchParams({id:item.id}),{signal:AbortSignal.timeout(30000)});let data;try{data=await response.json()}catch{throw Error('当前静态版本不能即时核验，请在藏宝阁核实；完整本机服务支持核验。')}if(!response.ok)throw Error(data.error||'核验未完成');status.textContent=data.eligible?`已于 ${time(data.observedAt)} 核验：${money(data.item.priceCents)}，截止 ${time(data.item.lotteryEndsAt)}。`:'即时核验结果：该商品目前不满足有效抽签条件，不建议按旧记录参与。';if(data.eligible&&safeURL(data.item.url)){const link=document.createElement('a');link.href=data.item.url;link.target='_blank';link.rel='noopener noreferrer';link.className='lottery-link';link.textContent='前往藏宝阁查看已核验商品 ↗';status.append(link)}}catch(error){status.textContent=error.message}finally{button.disabled=false}}
async function refreshCollection(){if(collectionLoading)return;collectionLoading=true;try{let response=await fetch('/api/collection',{cache:'no-store'}),snapshot=false;if(!response.ok){response=await fetch('./collection.json',{cache:'no-store'});snapshot=true}if(!response.ok)throw Error('尚未生成全量收集进度');collection=await response.json();if(!Array.isArray(collection.entries))throw Error('收集进度暂不可用');const running=!snapshot&&collection.state==='running'&&Date.now()-Date.parse(collection.updatedAt)<90000;$('#collection-summary').textContent=`${snapshot?'发布时快照 · ':''}${running?'正在断点收集':'已保存收集进度'} · 保留 ${collection.totalItems.toLocaleString()} 件不同商品 · ${collection.pagesRead}/${collection.totalPages||'?'} 页 · ${collection.completedTypes}/${collection.totalTypes} 种分页遍历完成 · ${time(collection.updatedAt)}${collection.error?' · 本轮停止原因：'+collection.error:''}`;$('#collection-progress').max=collection.totalPages||1;$('#collection-progress').value=collection.pagesRead;$('#collection-types').innerHTML=collection.entries.map(entry=>`<tr><td><strong>${esc(entry.name)}</strong></td><td>${entry.count}</td><td>${entry.pagesRead} / ${entry.totalPages??'待获取'}</td><td>${entry.completedAt?'本轮分页已遍历':entry.totalPages?'断点续采中':'等待首次采集'}<small>${time(entry.lastSeen)}</small></td><td><button type="button" class="row-preview" data-inventory-type="${esc(entry.id)}">查看收集记录</button></td></tr>`).join('');document.querySelectorAll('[data-inventory-type]').forEach(button=>button.onclick=()=>{inventoryType=button.dataset.inventoryType;inventoryPage=1;$('#inventory-panel').hidden=false;loadInventory();$('#inventory-panel').scrollIntoView({behavior:'smooth',block:'start'})})}catch(error){$('#collection-summary').textContent=error.message}finally{collectionLoading=false}}
async function loadInventory(){const token=++inventoryRequest;$('#inventory-title').textContent=(collection?.entries.find(e=>e.id===inventoryType)?.name??'谪星')+' · 收集记录';$('#inventory-count').textContent='读取已保存的真实观察…';try{let response=await fetch('/api/inventory?'+new URLSearchParams({type:inventoryType,page:String(inventoryPage)})),data;if(response.ok)data=await response.json();else{response=await fetch('./inventory/'+encodeURIComponent(inventoryType)+'.json');if(!response.ok)throw Error('该类型记录尚未附带到此发布快照，请使用本机持续采集版查看。');const all=await response.json();data={count:all.count,items:all.items.slice((inventoryPage-1)*20,inventoryPage*20),page:inventoryPage,limit:20}}if(token!==inventoryRequest)return;inventoryResponse=data;$('#inventory-count').textContent=`累计 ${data.count} 件 · 最后观察信息，不等于当前在售或成交状态`;$('#inventory-rows').innerHTML=data.items.map((item,i)=>`<tr><td><strong>${esc(item.skin)}</strong><small>${esc(item.id)} · ${item.holesCount}孔</small></td><td>${esc(item.slots.join(' / ')||'无星格')}</td><td>${money(item.priceCents)}</td><td>☆ ${item.favorites}<small>${item.publicity?'观察时公示中':'观察时非公示'}</small></td><td>${time(item.observedAt)}<button type="button" class="row-preview" data-inventory-preview="${i}">预览</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">该类型还没有采集到真实商品。</td></tr>';const total=Math.max(1,Math.ceil(data.count/20));$('#inventory-page').textContent=`${inventoryPage} / ${total}`;$('#inventory-prev').disabled=inventoryPage<=1;$('#inventory-next').disabled=inventoryPage>=total;document.querySelectorAll('[data-inventory-preview]').forEach(button=>button.onclick=()=>window.dispatchEvent(new CustomEvent('preview-sample',{detail:data.items[Number(button.dataset.inventoryPreview)]})))}catch(error){if(token===inventoryRequest)$('#inventory-count').textContent=error.message}}
$('#inventory-prev').onclick=()=>{inventoryPage--;loadInventory()};$('#inventory-next').onclick=()=>{inventoryPage++;loadInventory()};
for(const id of ['lottery-filter-skin','lottery-filter-holes','lottery-filter-state'])$('#'+id).onchange=render;
window.addEventListener('auth-changed',event=>{auth=event.detail;render()});window.addEventListener('market-data',event=>{marketData=event.detail;render()});window.addEventListener('storage',event=>{if(event.key==='zx-lottery-subscriptions'){subscriptions=validSubscriptions(read(event.key,[]));render()}});
render();refreshSharedAuth();refreshCollection();setInterval(()=>{render();if(!panel.hidden){refreshLottery();refreshCollection()}},30000);
fetch('./catalog.json').then(r=>r.json()).then(data=>{catalog=data.items;for(const id of ['lottery-sub-skin','lottery-filter-skin']){const select=$('#'+id),selected=select.value;select.replaceChildren();if(id==='lottery-filter-skin'){const all=document.createElement('option');all.value='';all.textContent='全部谪星';select.append(all)}for(const entry of catalog){const option=document.createElement('option');option.value=entry.name;option.textContent=entry.name;select.append(option)}if([...select.options].some(o=>o.value===selected))select.value=selected}updateSubHoles()}).catch(()=>{$('#lottery-message').textContent='谪星目录暂不可用，请刷新重试。'});
function updateSubHoles(){const select=$('#lottery-sub-holes'),selected=select.value,count=catalog.find(entry=>entry.name===$('#lottery-sub-skin').value)?.slotNames?.length??4;select.replaceChildren();for(let n=0;n<=count;n++){const option=document.createElement('option');option.value=String(n);option.textContent=n+'孔';select.append(option)}if([...select.options].some(option=>option.value===selected))select.value=selected}$('#lottery-sub-skin').onchange=updateSubHoles;
if(location.hash==='#lottery')nav.click();

setInterval(()=>{if(!panel.hidden)renderLiveStatus(marketData.lottery??{})},1000);
